function netMusPan(){
  var up, on, pan=0;
  if(!NET.musP) return 0;
  up=(NET.same==='p2')?!!NET.hostSeed:!!NET.specG;
  on=(typeof netSndWhoOn==='function')?netSndWhoOn():true;
  if(on&&up&&netSndWho()==='both'&&netSndSplitOn()) pan=(NET.same==='p2')?1:-1;
  try{ NET.musP.pan.value=pan; }catch(e){}
  return pan;
}
